"""Load builder-defined hooks from a packaged snapshot."""

from __future__ import annotations

import importlib.util
import sys
from contextlib import contextmanager
from pathlib import Path
from typing import Callable, Iterator

import structlog

from rasa.mantle.hooks.constants import HOOKS_DIR_NAME, HOOKS_FILE_NAME
from rasa.mantle.hooks.decorators import _is_hook_function
from rasa.mantle.hooks.exceptions import HookLoadingError
from rasa.mantle.hooks.registry import HookRegistry
from rasa.mantle.snapshot_lib import (
    evict_snapshot_lib_modules,
    record_snapshot_lib_modules,
)

structlogger = structlog.get_logger(__name__)


def _is_nested_hook_file(module_path: Path) -> bool:
    return module_path.name != "__init__.py" and "__pycache__" not in module_path.parts


def iter_hook_module_paths(snapshot_root: Path) -> list[Path]:
    """Return ``hooks.py`` plus nested ``hooks/**/*.py`` sources, if present."""
    paths: list[Path] = []
    single_file = snapshot_root / HOOKS_FILE_NAME
    if single_file.is_file():
        paths.append(single_file)
    hooks_dir = snapshot_root / HOOKS_DIR_NAME
    if hooks_dir.is_dir():
        paths.extend(
            sorted(
                path for path in hooks_dir.rglob("*.py") if _is_nested_hook_file(path)
            )
        )
    return paths


@contextmanager
def _importable_snapshot_root(snapshot_root: Path) -> Iterator[None]:
    path_entry = str(snapshot_root)
    already_present = path_entry in sys.path
    if not already_present:
        sys.path.insert(0, path_entry)
    try:
        yield
    finally:
        if not already_present:
            try:
                sys.path.remove(path_entry)
            except ValueError:
                structlogger.debug(
                    "mantle.hook_loader.sys_path_entry_already_removed",
                    path_entry=path_entry,
                )
        record_snapshot_lib_modules()


def _evict_snapshot_hooks_packages() -> None:
    """Drop ``hooks`` / ``hooks.*`` left by a previous snapshot's package imports."""
    for module_name in [
        name for name in sys.modules if name == "hooks" or name.startswith("hooks.")
    ]:
        sys.modules.pop(module_name, None)


def _hooks_defined_in_module(
    module: object, *, module_path: Path
) -> list[Callable[..., object]]:
    """Hook callables defined in *module*, not imported into it.

    Aliases of the same function (``also = log_request``) are registered once.
    """
    module_name = getattr(module, "__name__", None)
    hooks: dict[int, Callable[..., object]] = {}
    skipped: set[int] = set()
    for obj in vars(module).values():
        if not _is_hook_function(obj):
            continue
        defined_in = getattr(obj, "__module__", None)
        if defined_in != module_name:
            obj_id = id(obj)
            if obj_id not in skipped:
                skipped.add(obj_id)
                structlogger.debug(
                    "mantle.hook_loader.skipped_imported_hook",
                    hook_name=getattr(obj, "__name__", repr(obj)),
                    hook_module=defined_in,
                    loaded_module=module_name,
                    module_path=str(module_path),
                )
            continue
        hooks.setdefault(id(obj), obj)
    return list(hooks.values())


def _load_hook_module(
    module_path: Path,
    module_name: str,
    snapshot_root: Path,
) -> list[Callable[..., object]]:
    spec = importlib.util.spec_from_file_location(module_name, module_path)
    if spec is None or spec.loader is None:
        raise HookLoadingError(f"Unable to create an import spec for {module_path}.")

    module = importlib.util.module_from_spec(spec)
    try:
        # TODO(security): exec_module runs arbitrary Python from the model archive
        # without sandboxing. Tracked in ENG-2931.
        with _importable_snapshot_root(snapshot_root):
            spec.loader.exec_module(module)
    except Exception as exc:
        raise HookLoadingError(
            f"Failed to import hook module {module_path}: {exc}"
        ) from exc

    return _hooks_defined_in_module(module, module_path=module_path)


def _register_module_hooks(
    registry: HookRegistry,
    module_path: Path,
    module_name: str,
    snapshot_root: Path,
) -> None:
    for func in _load_hook_module(module_path, module_name, snapshot_root):
        registry.register_function(func, module_path=str(module_path))


def _load_hooks_from_dir(
    registry: HookRegistry,
    hooks_dir: Path,
    module_prefix: str,
    snapshot_root: Path,
) -> None:
    for module_path in sorted(hooks_dir.rglob("*.py")):
        if not _is_nested_hook_file(module_path):
            continue
        relative = module_path.relative_to(hooks_dir)
        # Join with "__" so hooks/foo/bar.py and hooks/foo_bar.py do not collide.
        stem_parts = relative.with_suffix("").parts
        module_name = f"{module_prefix}_{'__'.join(stem_parts)}"
        _register_module_hooks(registry, module_path, module_name, snapshot_root)


def load_hooks(snapshot_root: Path, *, evict_lib: bool = True) -> HookRegistry:
    """Discover and import hook modules from a snapshot root.

    Supports both a single ``hooks.py`` at the snapshot root and a recursive
    ``hooks/**/*.py`` tree. ``__init__.py`` is skipped. Missing sources produce
    an empty registry.

    Pass ``evict_lib=False`` when tools have already been loaded from the same
    snapshot in this process (model load), so ``lib`` modules those tools
    imported are not dropped and re-imported.
    """
    _evict_snapshot_hooks_packages()
    if evict_lib:
        evict_snapshot_lib_modules()
    registry = HookRegistry.empty()

    single_file = snapshot_root / HOOKS_FILE_NAME
    if single_file.is_file():
        _register_module_hooks(
            registry, single_file, "_mantle_hooks_root", snapshot_root
        )

    hooks_dir = snapshot_root / HOOKS_DIR_NAME
    if hooks_dir.is_dir():
        _load_hooks_from_dir(registry, hooks_dir, "_mantle_hooks", snapshot_root)

    structlogger.debug(
        "mantle.hook_loader.load_hooks.finished",
        observer_count=registry.observer_count,
        modifier_count=registry.modifier_count,
    )
    return registry
